<?php
$admin_title='Customer Inquiries';require __DIR__.'/layout_top.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(($_POST['action']??'')==='delete'){$pdo->prepare('DELETE FROM contact_messages WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Inquiry deleted.');redirect('admin/messages.php');}if(($_POST['action']??'')==='read'){$pdo->prepare("UPDATE contact_messages SET status='read' WHERE id=?")->execute([(int)$_POST['id']]);redirect('admin/messages.php');}}$messages=$pdo->query('SELECT * FROM contact_messages ORDER BY created_at DESC')->fetchAll();
?>
<span class="eyebrow" style="color:#ae7d2c">Customer follow-up</span><h1>Inquiries</h1><div class="grid"><?php if(!$messages):?><div class="card">No inquiries yet.</div><?php endif;?><?php foreach($messages as $m):?><article class="card"><div style="display:flex;justify-content:space-between;gap:15px"><div><h3 style="margin:0"><?=e($m['subject'])?></h3><p><b><?=e($m['name'])?></b> · <?=e($m['email'])?> <?= $m['phone']?' · '.e($m['phone']):'' ?></p></div><span class="badge <?= $m['status']==='new'?'stock-low':'stock-in' ?>"><?=e($m['status'])?></span></div><p><?=nl2br(e($m['message']))?></p><div class="actions"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="read"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="button small outline">Mark read</button></form><form method="post" data-confirm="delete"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$m['id']?>"><button class="button small danger">Delete</button></form></div></article><?php endforeach;?></div>
